mapper.select:
SELECT tr.orgId, tr.orgName, tr.treatDate, tr.patientId, tr.patientName, tr.mobile, tr.gender, tr.treatType, tr.regDentistId, tr.regDentistName, tr.appointTime, tr.appointDuration, tr.appointContent, tr.regTime, tr.treatStartTime, tr.treatEndTime, tr.treatWaitingTime, tr.treatExpendTime FROM ( SELECT btp.org_id AS orgId, bo.abbreviation AS orgName, DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) AS treatDate, btp.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.treat_type AS treatType, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName, DATE_FORMAT( btp.appoint_start_time, '%H:%i' ) AS appointTime, btp.appoint_duration AS appointDuration, btp.appoint_content AS appointContent, DATE_FORMAT( btp.registered_time, '%H:%i' ) AS regTime, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) AS treatStartTime, DATE_FORMAT( btp.treat_end_time, '%H:%i' ) AS treatEndTime, TIMESTAMPDIFF( MINUTE, btp.registered_time, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) ) AS treatWaitingTime, TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ) AS treatExpendTime FROM base_treatment_process btp LEFT JOIN base_organization bo ON btp.org_id = bo.org_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) tr
and tr.orgId = #{query.orgId}
and concat(ifnull(tr.patientName, ''), ifnull(tr.pinyinName, ''), ifnull(tr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and tr.treatDate >= #{query.treatStartDate}
and tr.treatDate <= #{query.treatEndDate}
and tr.regDentistId in
#{item}
ORDER BY tr.treatDate DESC

SELECT tmr.treatmentId, tmr.assistant1Id, tmr.assistant1Name, tmr.assistant2Id, tmr.assistant2Name, tmr.assistant3Id, tmr.assistant3Name, tmr.matchingDentistId, tmr.matchingDentistName, tmr.patientId, tmr.patientName, tmr.mobile, tmr.matchingDate, tmr.treatStartTime, tmr.treatEndTime, tmr.matchingDuration FROM ( SELECT btp.org_id as orgId, btp.treatment_id AS treatmentId, btp.assistant_1 AS assistant1Id, be1.employee_name AS assistant1Name, btp.assistant_2 AS assistant2Id, be2.employee_name AS assistant2Name, btp.assistant_3 AS assistant3Id, be3.employee_name AS assistant3Name, btp.registered_dentist_id AS matchingDentistId, be.employee_name AS matchingDentistName, btp.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) AS matchingDate, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) AS treatStartTime, DATE_FORMAT( btp.treat_end_time, '%H:%i' ) AS treatEndTime, TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ) AS matchingDuration FROM base_treatment_process btp LEFT JOIN base_employee be1 ON btp.assistant_1 = be1.user_id LEFT JOIN base_employee be2 ON btp.assistant_2 = be1.user_id LEFT JOIN base_employee be3 ON btp.assistant_3 = be1.user_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id WHERE btp.treatment_id IS NOT NULL AND ( btp.assistant_1 IS NOT NULL OR btp.assistant_2 IS NOT NULL OR btp.assistant_3 IS NOT NULL ) ) tmr
and tmr.orgId = #{query.orgId}
and concat(ifnull(tmr.patientName, ''), ifnull(tmr.pinyinName, ''), ifnull(tmr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and tmr.matchingDate >= #{query.matchingStartDate}
and tmr.matchingDate <= #{query.matchingEndDate}
and tmr.matchingDentistId in
#{item}
ORDER BY tmr.matchingDate DESC

SELECT btp.treatment_id AS treatmentId, btp.treatDate, btp.patient_id as patientId, btp.patientName, btp.mobile, DATE_FORMAT(btp.treatStartTime, '%Y-%m-%d %H:%i'), DATE_FORMAT(btp.treatEndTime, '%Y-%m-%d %H:%i'), btp.matchDuration FROM ( SELECT btp.treatment_id, DATE_FORMAT(btp.treat_start_time, '%Y-%m-%d') as treatDate, btp.patient_id, bp.`name` AS patientName, bp.mobile, bp.pinyin_name AS pinyinName, btp.treat_start_time AS treatStartTime, btp.treat_end_time AS treatEndTime, SUM( btp.matchTime ) AS matchDuration FROM ( SELECT btp.treatment_id, btp.patient_id, btp.assistant_1, btp.treat_start_time, btp.treat_end_time, IF ( TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ) = 0, 1, TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time )) AS matchTime FROM base_treatment_process btp
and btp.treat_end_time IS NOT NULL
AND btp.org_id = #{query.orgId}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
AND btp.assistant_1 = #{query.assistantId}
AND btp.assistant_2 = #{query.assistantId}
AND btp.assistant_3 = #{query.assistantId}
) btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id GROUP BY btp.treatment_id ) btp
and concat(IFNULL(btp.patientName, ''), IFNULL(btp.pinyinName, ''), IFNULL(btp.mobile, '')) like concat('%', #{query.keyword}, '%')
and btp.treatStartTime >= #{query.treatStartDate}
and btp.treatStartTime <= #{query.treatEndDate}
